DROP TABLE IF EXISTS `reminder_followups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reminder_followups` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vaccination_id` int NOT NULL,
  `sms_sent` tinyint(1) DEFAULT '0',
  `sms_sent_at` datetime DEFAULT NULL,
  `is_followed_up` tinyint(1) DEFAULT '0',
  `followed_up_at` datetime DEFAULT NULL,
  `owner_responded` tinyint(1) DEFAULT '0',
  `is_resolved` tinyint(1) DEFAULT '0',
  `notes` text COLLATE utf8mb4_persian_ci,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_remind_resolved` (`is_resolved`),
  KEY `idx_remind_vacc` (`vaccination_id`),
  CONSTRAINT `reminder_followups_ibfk_1` FOREIGN KEY (`vaccination_id`) REFERENCES `vaccinations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=403 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_persian_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

